// ============================================================================
// Zone management
// ============================================================================
type Zone = {
  id: string;
  name: string;
  color: string;
  zips: string[];
  locked: boolean;
};

const ZONE_PALETTE = [
  "#E63946", "#F4A261", "#2A9D8F", "#264653", "#9D4EDD",
  "#06AED5", "#F72585", "#80B918", "#7209B7", "#F77F00",
];

function heatColor(count: number, max: number): string {
  if (!count || max <= 0) return "#e8e6df";
  const t = Math.sqrt(count / max);
  return d3.interpolateYlOrRd(0.18 + t * 0.78);
}

function darken(hex: string, k: number): string {
  const c = d3.color(hex);
  if (!c) return hex;
  return (c as any).darker(k).formatHex();
}

export default function ZipCodeMap() {
  const mapRef = useRef<HTMLDivElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);

  const [stateFilter, setStateFilter] = useState<StateFilter>("all");
  const [showLabels, setShowLabels] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>("3d");
  const [colorBy, setColorBy] = useState<"heat" | "zone">("heat");
  const [selectedZips, setSelectedZips] = useState<Set<string>>(new Set());
  // 3D camera: azimuth (yaw) and tilt (0 = top-down, π/2 = horizon)
  const [azimuth, setAzimuth] = useState(0);
  const [tilt, setTilt] = useState(Math.PI * 0.32); // ~58° from top-down
  const [zones, setZones] = useState<Zone[]>([]);
  const [activeZoneId, setActiveZoneId] = useState<string | null>(null);

  // Persistence
  const [loadStatus, setLoadStatus] = useState<"loading" | "ok" | "error">(
    "loading"
  );
  const [saveStatus, setSaveStatus] = useState<
    "idle" | "saving" | "saved" | "error"
  >("idle");
  const loadedRef = useRef(false);
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Load zones once on mount
  useEffect(() => {
    let cancelled = false;
    fetch("/api/zones")
      .then((r) => (r.ok ? r.json() : Promise.reject(r)))
      .then((j) => {
        if (cancelled) return;
        if (Array.isArray(j.zones)) setZones(j.zones);
        loadedRef.current = true;
        setLoadStatus("ok");
      })
      .catch(() => {
        if (cancelled) return;
        loadedRef.current = true;
        setLoadStatus("error");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // Keep activeZoneId pointing at a valid unlocked zone — picks the first one
  // automatically after load / delete so "Assign to active zone" works.
  useEffect(() => {
    if (zones.length === 0) return;
    const valid =
      !!activeZoneId &&
      zones.some((z) => z.id === activeZoneId && !z.locked);
    if (!valid) {
      const firstUnlocked = zones.find((z) => !z.locked);
      if (firstUnlocked) setActiveZoneId(firstUnlocked.id);
    }
  }, [zones, activeZoneId]);

  // Debounced auto-save when zones change (after initial load)
  useEffect(() => {
    if (!loadedRef.current) return;
    setSaveStatus("saving");
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(async () => {
      try {
        const r = await fetch("/api/zones", {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ zones }),
        });
        setSaveStatus(r.ok ? "saved" : "error");
      } catch {
        setSaveStatus("error");
      }
    }, 800);
    return () => {
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    };
  }, [zones]);

  const maxCount = useMemo(
    () => Math.max(1, ...Object.values(JOB_COUNTS)),
    []
  );

  const zipToZone = useMemo(() => {
    const m = new Map<string, Zone>();
    zones.forEach((z) => z.zips.forEach((zip) => m.set(zip, z)));
    return m;
  }, [zones]);

  // Refs for click-handler stability (avoid re-rendering full d3 on every click)
  const selectedRef = useRef(selectedZips);
  const zipToZoneRef = useRef(zipToZone);
  selectedRef.current = selectedZips;
  zipToZoneRef.current = zipToZone;

  function toggleZip(zip: string) {
    const z = zipToZoneRef.current.get(zip);
    if (z?.locked) return;
    setSelectedZips((prev) => {
      const next = new Set(prev);
      if (next.has(zip)) next.delete(zip);
      else next.add(zip);
      return next;
    });
  }

  function createZone() {
    const id = `zone-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const name = `Zone ${String.fromCharCode(65 + zones.length)}`;
    const color = ZONE_PALETTE[zones.length % ZONE_PALETTE.length];
    setZones([...zones, { id, name, color, zips: [], locked: false }]);
    setActiveZoneId(id);
  }

  function assignSelectionToActive() {
    if (!activeZoneId || selectedZips.size === 0) return;
    setZones(
      zones.map((z) => {
        if (z.locked) return z;
        if (z.id === activeZoneId) {
          const merged = Array.from(new Set([...z.zips, ...selectedZips]));
          return { ...z, zips: merged };
        }
        return { ...z, zips: z.zips.filter((zip) => !selectedZips.has(zip)) };
      })
    );
    setSelectedZips(new Set());
  }

  function removeFromZone(zoneId: string, zip: string) {
    setZones(
      zones.map((z) =>
        z.id === zoneId && !z.locked
          ? { ...z, zips: z.zips.filter((q) => q !== zip) }
          : z
      )
    );
  }

  function toggleLock(id: string) {
    setZones(zones.map((z) => (z.id === id ? { ...z, locked: !z.locked } : z)));
  }

  function deleteZone(id: string) {
    const z = zones.find((q) => q.id === id);
    if (z?.locked) return;
    setZones(zones.filter((q) => q.id !== id));
    if (activeZoneId === id) setActiveZoneId(null);
  }

  function renameZone(id: string, name: string) {
    setZones(zones.map((z) => (z.id === id ? { ...z, name } : z)));
  }

  function copyZips(zone: Zone) {
    const text = zone.zips.join(", ");
    if (typeof navigator !== "undefined" && navigator.clipboard) {
      navigator.clipboard.writeText(text);
    }
  }

  useEffect(() => {
    if (!mapRef.current) return;
    mapRef.current.innerHTML = "";

    const width = 760;
    const height = 640;

    const svg = d3
      .select(mapRef.current)
      .append("svg")
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("width", "100%")
      .style("display", "block");

    const filtered = {
      type: "FeatureCollection",
      features: GEO_DATA.features.filter(
        (f: any) =>
          stateFilter === "all" || f.properties.state === stateFilter
      ),
    };

    const projection = d3
      .geoMercator()
      .fitSize([width - 60, height - 180], filtered as any);
    const [tx, ty] = projection.translate();
    projection.translate([tx + 30, ty + 140]); // leave headroom for extruded towers
    const path = d3.geoPath(projection);

    const tooltip = d3
      .select(tooltipRef.current)
      .style("position", "absolute")
      .style("pointer-events", "none")
      .style("background", "#fff")
      .style("border", "1px solid #d3d1c7")
      .style("border-radius", "6px")
      .style("padding", "6px 10px")
      .style("font-size", "12px")
      .style("opacity", 0)
      .style("z-index", 10)
      .style("white-space", "nowrap")
      .style("box-shadow", "0 2px 8px rgba(0,0,0,0.08)");

    const fillFor = (zip: string) => {
      if (colorBy === "zone") {
        const z = zipToZone.get(zip);
        if (z) return z.color;
        return "#e8e6df";
      }
      return heatColor(JOB_COUNTS[zip] || 0, maxCount);
    };

    // Stroke per region: selection wins, then zone-membership shows zone color
    // (so zone assignment is visible even in heatmap mode), else default white.
    const strokeFor = (zip: string) => {
      if (selectedZips.has(zip)) return { color: "#1a1a1a", width: 2.5 };
      const z = zipToZone.get(zip);
      if (z) return { color: z.color, width: 2.2 };
      return { color: "#fff", width: 0.6 };
    };

    const showTip = (zip: string, city: string, state: string) => {
      const count = JOB_COUNTS[zip] || 0;
      const z = zipToZone.get(zip);
      const zoneTag = z
        ? `<div style="margin-top:3px;color:${z.color};font-weight:600">${z.name}${z.locked ? " (locked)" : ""}</div>`
        : "";
      tooltip
        .style("opacity", 1)
        .html(
          `<strong>${zip}</strong> &middot; ${city} (${state})` +
            `<div style="margin-top:2px;color:#444">${count.toLocaleString()} jobs</div>` +
            zoneTag
        );
    };

    const moveTip = (event: MouseEvent) => {
      const rect = mapRef.current!.getBoundingClientRect();
      tooltip
        .style("left", event.clientX - rect.left + 12 + "px")
        .style("top", event.clientY - rect.top + 12 + "px");
    };

    const hideTip = () => tooltip.style("opacity", 0);

    const g = svg.append("g");

    if (viewMode === "3d") {
      // ----- True 3D extrusion with yaw + tilt camera -----
      // Compute pivot (center of projected bbox) so rotation feels centered.
      let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
      filtered.features.forEach((f: any) => {
        const b = path.bounds(f);
        if (b[0][0] < minX) minX = b[0][0];
        if (b[1][0] > maxX) maxX = b[1][0];
        if (b[0][1] < minY) minY = b[0][1];
        if (b[1][1] > maxY) maxY = b[1][1];
      });
      const pivotX = (minX + maxX) / 2;
      const pivotY = (minY + maxY) / 2;

      const cosA = Math.cos(azimuth);
      const sinA = Math.sin(azimuth);
      const cosT = Math.cos(tilt);
      const sinT = Math.sin(tilt);

      // (x,y in projected ground plane, z up) → screen (sx, sy)
      const tx = (x: number, y: number, z: number): [number, number] => {
        const u = x - pivotX;
        const v = y - pivotY;
        const u1 = u * cosA - v * sinA;
        const v1 = u * sinA + v * cosA;
        return [pivotX + u1, pivotY + v1 * cosT - z * sinT];
      };

      // groundDepth = v1 (after yaw); larger = closer to camera (drawn last)
      const groundDepth = (x: number, y: number) => {
        const u = x - pivotX;
        const v = y - pivotY;
        return u * sinA + v * cosA;
      };

      const ringPath = (ring: number[][], h: number) => {
        const pts = ring.map((c) => {
          const p = projection(c as any)!;
          return tx(p[0], p[1], h);
        });
        return (
          "M" +
          pts.map((p) => `${p[0].toFixed(2)},${p[1].toFixed(2)}`).join("L") +
          "Z"
        );
      };

      const items = filtered.features.map((f: any) => {
        const zip = f.properties.zip;
        const count = JOB_COUNTS[zip] || 0;
        const h = Math.sqrt(count / maxCount) * 140;
        const c = path.centroid(f);
        const top = tx(c[0], c[1], h);
        return {
          f,
          zip,
          count,
          h,
          gx: c[0],
          gy: c[1],
          depth: groundDepth(c[0], c[1]),
          topX: top[0],
          topY: top[1],
        };
      });
      items.sort((a: any, b: any) => a.depth - b.depth);

      items.forEach((it: any) => {
        const baseFill = fillFor(it.zip);
        const wallFill = darken(baseFill, 0.7);
        const inLockedZone = !!zipToZone.get(it.zip)?.locked;

        const grp = g.append("g").attr("data-zip", it.zip);

        const polys =
          it.f.geometry.type === "Polygon"
            ? [it.f.geometry.coordinates]
            : it.f.geometry.coordinates;

        // Walls: only edges whose midpoint is "in front of" the centroid
        // in the rotated ground plane (i.e., greater groundDepth).
        for (const poly of polys) {
          const ring = poly[0];
          const projected = ring.map((c: number[]) => projection(c as any)!);
          for (let i = 0; i < projected.length - 1; i++) {
            const a = projected[i];
            const b = projected[i + 1];
            const midDepth = groundDepth(
              (a[0] + b[0]) / 2,
              (a[1] + b[1]) / 2
            );
            if (midDepth > it.depth) {
              const aBot = tx(a[0], a[1], 0);
              const bBot = tx(b[0], b[1], 0);
              const aTop = tx(a[0], a[1], it.h);
              const bTop = tx(b[0], b[1], it.h);
              grp
                .append("path")
                .attr(
                  "d",
                  `M${aBot[0]},${aBot[1]} L${bBot[0]},${bBot[1]} L${bTop[0]},${bTop[1]} L${aTop[0]},${aTop[1]} Z`
                )
                .attr("fill", wallFill)
                .attr("stroke", "#fff")
                .attr("stroke-width", 0.4)
                .style("pointer-events", "none");
            }
          }
        }

        // Top face — built ring-by-ring so MultiPolygons render correctly.
        const topD = polys
          .map((poly: number[][][]) =>
            poly.map((ring) => ringPath(ring, it.h)).join(" ")
          )
          .join(" ");

        const stk = strokeFor(it.zip);
        grp
          .append("path")
          .attr("d", topD)
          .attr("fill", baseFill)
          .attr("stroke", stk.color)
          .attr("stroke-width", stk.width)
          .style("cursor", inLockedZone ? "not-allowed" : "pointer")
          .on("mouseover", function () {
            d3.select(this).attr("stroke-width", Math.max(stk.width, 1.8));
            showTip(it.zip, it.f.properties.city, it.f.properties.state);
          })
          .on("mousemove", moveTip)
          .on("mouseout", function () {
            d3.select(this).attr("stroke-width", stk.width);
            hideTip();
          })
          .on("click", () => toggleZip(it.zip));

        if (showLabels && it.h > 14) {
          grp
            .append("text")
            .attr("x", it.topX)
            .attr("y", it.topY - 2)
            .attr("text-anchor", "middle")
            .attr("font-size", "8px")
            .attr("font-weight", 600)
            .attr("fill", "#1a1a1a")
            .attr("stroke", "#fff")
            .attr("stroke-width", 2)
            .attr("paint-order", "stroke")
            .style("pointer-events", "none")
            .text(it.zip);
        }
      });
    } else {
      // ----- 2D choropleth (yaw-rotatable) -----
      // Pivot = center of projected bbox of visible features.
      let minX = Infinity,
        maxX = -Infinity,
        minY = Infinity,
        maxY = -Infinity;
      filtered.features.forEach((f: any) => {
        const b = path.bounds(f);
        if (b[0][0] < minX) minX = b[0][0];
        if (b[1][0] > maxX) maxX = b[1][0];
        if (b[0][1] < minY) minY = b[0][1];
        if (b[1][1] > maxY) maxY = b[1][1];
      });
      const pivotX = (minX + maxX) / 2;
      const pivotY = (minY + maxY) / 2;
      const angleDeg = (azimuth * 180) / Math.PI;
      const cosA = Math.cos(azimuth);
      const sinA = Math.sin(azimuth);

      // Polygons rendered inside a rotated group so paths don't have to be
      // recomputed each frame.
      const polyG = g
        .append("g")
        .attr("transform", `rotate(${angleDeg} ${pivotX} ${pivotY})`);
      polyG
        .selectAll("path")
        .data(filtered.features)
        .join("path")
        .attr("d", (d: any) => path(d) as string)
        .attr("fill", (d: any) => fillFor(d.properties.zip))
        .attr("fill-opacity", 0.88)
        .attr("stroke", (d: any) => strokeFor(d.properties.zip).color)
        .attr("stroke-width", (d: any) => strokeFor(d.properties.zip).width)
        .style("cursor", (d: any) =>
          zipToZone.get(d.properties.zip)?.locked ? "not-allowed" : "pointer"
        )
        .on("mouseover", function (_e: any, d: any) {
          const s = strokeFor(d.properties.zip);
          d3.select(this).attr("stroke-width", Math.max(s.width, 1.8));
          showTip(d.properties.zip, d.properties.city, d.properties.state);
        })
        .on("mousemove", moveTip)
        .on("mouseout", function (_e: any, d: any) {
          d3.select(this).attr(
            "stroke-width",
            strokeFor(d.properties.zip).width
          );
          hideTip();
        })
        .on("click", (_e: any, d: any) => toggleZip(d.properties.zip));

      // Labels in a NON-rotated group, positioned at the rotated centroid so
      // text stays upright at any yaw angle.
      if (showLabels) {
        const rotated = (cx: number, cy: number) => {
          const dx = cx - pivotX;
          const dy = cy - pivotY;
          return [pivotX + dx * cosA - dy * sinA, pivotY + dx * sinA + dy * cosA];
        };
        g.selectAll("text")
          .data(filtered.features)
          .join("text")
          .attr("x", (d: any) => {
            const c = path.centroid(d);
            return rotated(c[0], c[1])[0];
          })
          .attr("y", (d: any) => {
            const c = path.centroid(d);
            return rotated(c[0], c[1])[1];
          })
          .attr("text-anchor", "middle")
          .attr("dominant-baseline", "middle")
          .attr("font-size", "8px")
          .attr("font-weight", 500)
          .attr("fill", "#1a1a1a")
          .attr("stroke", "#fff")
          .attr("stroke-width", 2)
          .attr("paint-order", "stroke")
          .style("pointer-events", "none")
          .text((d: any) => d.properties.zip);
      }
    }
  }, [stateFilter, showLabels, viewMode, colorBy, selectedZips, zones, zipToZone, maxCount, azimuth, tilt]);

  // Stats
  const totalJobs = useMemo(
    () => Object.values(JOB_COUNTS).reduce((a, b) => a + b, 0),
    []
  );
  const assignedZips = useMemo(
    () => new Set(zones.flatMap((z) => z.zips)),
    [zones]
  );
  const visibleZips = useMemo(
    () =>
      GEO_DATA.features
        .filter(
          (f: any) =>
            stateFilter === "all" || f.properties.state === stateFilter
        )
        .map((f: any) => f.properties.zip as string),
    [stateFilter]
  );

  function zoneJobTotal(z: Zone) {
    return z.zips.reduce((sum, zip) => sum + (JOB_COUNTS[zip] || 0), 0);
  }

  function zoneBreakdown(z: Zone) {
    const totals: Record<string, number> = {};
    for (const zip of z.zips) {
      const types = JOB_TYPES_BY_ZIP[zip];
      if (!types) continue;
      for (const [cat, n] of Object.entries(types)) {
        totals[cat] = (totals[cat] || 0) + n;
      }
    }
    const total = Object.values(totals).reduce((a, b) => a + b, 0);
    return JOB_CATEGORIES.map((c) => ({
      name: c.name,
      color: c.color,
      count: totals[c.name] || 0,
      pct: total > 0 ? (totals[c.name] || 0) / total : 0,
    })).filter((r) => r.count > 0);
  }

  // Heatmap legend stops
  const heatStops = [0, 0.25, 0.5, 0.75, 1].map((t) => ({
    t,
    color: heatColor(t * maxCount, maxCount),
    label: Math.round(t * maxCount).toString(),
  }));

  return (
    <div
      style={{
        maxWidth: 1180,
        margin: "0 auto",
        fontFamily: "system-ui, sans-serif",
      }}
    >
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "minmax(0, 1fr) 340px",
          gap: 20,
          alignItems: "start",
        }}
      >
        {/* ============== LEFT: map + controls ============== */}
        <div>
          {/* Toolbar */}
          <div
            style={{
              marginBottom: 12,
              display: "flex",
              gap: 10,
              alignItems: "center",
              flexWrap: "wrap",
              fontSize: 13,
              color: "#444",
            }}
          >
            <div
              style={{
                display: "inline-flex",
                border: "1px solid #d3d1c7",
                borderRadius: 6,
                overflow: "hidden",
              }}
            >
              {(["3d", "2d"] as ViewMode[]).map((m) => (
                <button
                  key={m}
                  onClick={() => setViewMode(m)}
                  style={{
                    padding: "5px 12px",
                    border: "none",
                    background: viewMode === m ? "#1a1a1a" : "#fff",
                    color: viewMode === m ? "#fff" : "#1a1a1a",
                    cursor: "pointer",
                    fontSize: 13,
                    fontWeight: 500,
                  }}
                >
                  {m.toUpperCase()}
                </button>
              ))}
            </div>

            <div
              style={{
                display: "inline-flex",
                border: "1px solid #d3d1c7",
                borderRadius: 6,
                overflow: "hidden",
              }}
            >
              {(["heat", "zone"] as const).map((m) => (
                <button
                  key={m}
                  onClick={() => setColorBy(m)}
                  style={{
                    padding: "5px 10px",
                    border: "none",
                    background: colorBy === m ? "#1a1a1a" : "#fff",
                    color: colorBy === m ? "#fff" : "#1a1a1a",
                    cursor: "pointer",
                    fontSize: 12,
                  }}
                >
                  {m === "heat" ? "Heatmap" : "Zones"}
                </button>
              ))}
            </div>

            <select
              value={stateFilter}
              onChange={(e) => setStateFilter(e.target.value as StateFilter)}
              style={{ fontSize: 13, padding: "4px 8px" }}
            >
              <option value="all">CT + NY</option>
              <option value="CT">Connecticut</option>
              <option value="NY">New York</option>
            </select>

            <label>
              <input
                type="checkbox"
                checked={showLabels}
                onChange={(e) => setShowLabels(e.target.checked)}
              />{" "}
              Labels
            </label>

            <span style={{ marginLeft: "auto", color: "#666" }}>
              {totalJobs.toLocaleString()} jobs &middot; {visibleZips.length}{" "}
              regions
            </span>
          </div>

          {/* Map */}
          <div
            ref={mapRef}
            onMouseDown={(e) => {
              const startX = e.clientX;
              const startY = e.clientY;
              const startAz = azimuth;
              const startTilt = tilt;
              const allowTilt = viewMode === "3d";
              let dragged = false;
              const onMove = (ev: MouseEvent) => {
                const dx = ev.clientX - startX;
                const dy = ev.clientY - startY;
                if (!dragged && Math.hypot(dx, dy) < 3) return;
                dragged = true;
                setAzimuth(startAz - dx * 0.01);
                if (allowTilt) {
                  setTilt(
                    Math.max(
                      0.05,
                      Math.min(Math.PI / 2 - 0.05, startTilt - dy * 0.008)
                    )
                  );
                }
              };
              const onUp = () => {
                window.removeEventListener("mousemove", onMove);
                window.removeEventListener("mouseup", onUp);
                if (dragged) {
                  // Suppress the trailing click that follows a real drag
                  const swallow = (ce: MouseEvent) => {
                    ce.stopPropagation();
                    ce.preventDefault();
                    window.removeEventListener("click", swallow, true);
                  };
                  window.addEventListener("click", swallow, true);
                }
              };
              window.addEventListener("mousemove", onMove);
              window.addEventListener("mouseup", onUp);
            }}
            style={{
              width: "100%",
              position: "relative",
              background: "#f7f5f0",
              borderRadius: 12,
              border: "1px solid #e5e3dc",
              overflow: "hidden",
              cursor: "grab",
              userSelect: "none",
            }}
          />
          <div ref={tooltipRef} />

          {/* Camera controls */}
          <div
            style={{
              marginTop: 8,
              display: "flex",
              alignItems: "center",
              gap: 12,
              fontSize: 11,
              color: "#666",
            }}
          >
            <span>Drag the map to rotate.</span>
            <label style={{ display: "flex", alignItems: "center", gap: 6 }}>
              Yaw
              <input
                type="range"
                min={-180}
                max={180}
                step={1}
                value={Math.round((azimuth * 180) / Math.PI)}
                onChange={(e) =>
                  setAzimuth((Number(e.target.value) * Math.PI) / 180)
                }
                style={{ width: 100 }}
              />
            </label>
            {viewMode === "3d" && (
              <label style={{ display: "flex", alignItems: "center", gap: 6 }}>
                Tilt
                <input
                  type="range"
                  min={3}
                  max={87}
                  step={1}
                  value={Math.round((tilt * 180) / Math.PI)}
                  onChange={(e) =>
                    setTilt((Number(e.target.value) * Math.PI) / 180)
                  }
                  style={{ width: 100 }}
                />
              </label>
            )}
            <button
              onClick={() => {
                setAzimuth(0);
                setTilt(Math.PI * 0.32);
              }}
              style={{
                padding: "3px 10px",
                fontSize: 11,
                background: "#fff",
                border: "1px solid #d3d1c7",
                borderRadius: 4,
                cursor: "pointer",
              }}
            >
              Reset view
            </button>
          </div>

          {/* Heatmap legend */}
          {colorBy === "heat" && (
            <div
              style={{
                marginTop: 10,
                display: "flex",
                alignItems: "center",
                gap: 8,
                fontSize: 11,
                color: "#666",
              }}
            >
              <span>Jobs:</span>
              <div style={{ display: "flex", flex: 1, height: 10, borderRadius: 3, overflow: "hidden" }}>
                {heatStops.map((s, i) => (
                  <div
                    key={i}
                    style={{ flex: 1, background: s.color }}
                    title={s.label}
                  />
                ))}
              </div>
              <span>0</span>
              <span style={{ marginLeft: "auto" }}>{maxCount}</span>
            </div>
          )}

          <div style={{ marginTop: 8, fontSize: 12, color: "#888" }}>
            Click a region to {selectedZips.size > 0 ? "toggle" : "select"} it.
            Selected zips become available for assignment to a zone in the panel
            on the right. Locked zones cannot be changed.
          </div>
        </div>

        {/* ============== RIGHT: zone panel ============== */}
        <div
          style={{
            border: "1px solid #e5e3dc",
            borderRadius: 12,
            padding: 14,
            background: "#fff",
            fontSize: 13,
          }}
        >
          {/* Selection summary */}
          <div style={{ marginBottom: 12 }}>
            <div style={{ fontWeight: 600, color: "#1a1a1a", marginBottom: 4 }}>
              Selection
            </div>
            <div style={{ color: "#666", fontSize: 12, marginBottom: 8 }}>
              {selectedZips.size === 0
                ? "No zips selected — click regions on the map."
                : `${selectedZips.size} zip${selectedZips.size === 1 ? "" : "s"} selected — ${Array.from(selectedZips)
                    .reduce((s, z) => s + (JOB_COUNTS[z] || 0), 0)
                    .toLocaleString()} jobs`}
            </div>
            {selectedZips.size > 0 && (
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 4,
                  marginBottom: 8,
                  maxHeight: 80,
                  overflowY: "auto",
                }}
              >
                {Array.from(selectedZips)
                  .sort()
                  .map((z) => (
                    <span
                      key={z}
                      onClick={() => toggleZip(z)}
                      style={{
                        background: "#f0eee6",
                        padding: "2px 6px",
                        borderRadius: 4,
                        fontSize: 11,
                        cursor: "pointer",
                        fontFamily: "monospace",
                      }}
                      title="Click to remove from selection"
                    >
                      {z} &times;
                    </span>
                  ))}
              </div>
            )}
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              <button
                onClick={assignSelectionToActive}
                disabled={!activeZoneId || selectedZips.size === 0}
                style={{
                  flex: 1,
                  padding: "6px 10px",
                  background:
                    !activeZoneId || selectedZips.size === 0 ? "#ccc" : "#1a1a1a",
                  color: "#fff",
                  border: "none",
                  borderRadius: 5,
                  cursor:
                    !activeZoneId || selectedZips.size === 0
                      ? "not-allowed"
                      : "pointer",
                  fontSize: 12,
                  fontWeight: 500,
                }}
              >
                Assign to active zone
              </button>
              <button
                onClick={() => setSelectedZips(new Set())}
                disabled={selectedZips.size === 0}
                style={{
                  padding: "6px 10px",
                  background: "#fff",
                  border: "1px solid #d3d1c7",
                  borderRadius: 5,
                  cursor: selectedZips.size === 0 ? "not-allowed" : "pointer",
                  fontSize: 12,
                }}
              >
                Clear
              </button>
            </div>
          </div>

          <div
            style={{
              borderTop: "1px solid #eee",
              paddingTop: 12,
              marginBottom: 8,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <div
              style={{
                fontWeight: 600,
                color: "#1a1a1a",
                display: "flex",
                alignItems: "center",
                gap: 8,
              }}
            >
              Zones ({zones.length})
              {(() => {
                const isErr =
                  loadStatus === "error" || saveStatus === "error";
                const text =
                  loadStatus === "loading"
                    ? "Loading…"
                    : loadStatus === "error"
                    ? "Load failed"
                    : saveStatus === "saving"
                    ? "Saving…"
                    : saveStatus === "saved"
                    ? "Saved"
                    : saveStatus === "error"
                    ? "Save failed"
                    : "";
                if (!text) return null;
                return (
                  <span
                    style={{
                      fontSize: 10,
                      fontWeight: 400,
                      color: isErr
                        ? "#a02525"
                        : saveStatus === "saved"
                        ? "#1d9e75"
                        : "#888",
                    }}
                  >
                    {text}
                  </span>
                );
              })()}
            </div>
            <button
              onClick={createZone}
              style={{
                padding: "4px 10px",
                background: "#1a1a1a",
                color: "#fff",
                border: "none",
                borderRadius: 5,
                cursor: "pointer",
                fontSize: 12,
              }}
            >
              + New zone
            </button>
          </div>

          {zones.length === 0 && (
            <div style={{ color: "#888", fontSize: 12, padding: "16px 0" }}>
              No zones yet. Create one, then click regions on the map and
              "Assign to active zone".
            </div>
          )}

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 8,
              maxHeight: 520,
              overflowY: "auto",
            }}
          >
            {zones.map((z) => {
              const isActive = activeZoneId === z.id;
              return (
                <div
                  key={z.id}
                  onClick={() => !z.locked && setActiveZoneId(z.id)}
                  style={{
                    border: `2px solid ${isActive ? z.color : "#e5e3dc"}`,
                    borderRadius: 8,
                    padding: 8,
                    cursor: z.locked ? "default" : "pointer",
                    background: isActive ? z.color + "10" : "#fafaf7",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      marginBottom: 4,
                    }}
                  >
                    <span
                      style={{
                        width: 12,
                        height: 12,
                        borderRadius: 3,
                        background: z.color,
                        flexShrink: 0,
                      }}
                    />
                    <input
                      value={z.name}
                      onChange={(e) => renameZone(z.id, e.target.value)}
                      onClick={(e) => e.stopPropagation()}
                      disabled={z.locked}
                      style={{
                        flex: 1,
                        border: "none",
                        background: "transparent",
                        fontSize: 13,
                        fontWeight: 600,
                        color: "#1a1a1a",
                        outline: "none",
                      }}
                    />
                    {isActive && !z.locked && (
                      <span
                        style={{
                          fontSize: 10,
                          color: z.color,
                          fontWeight: 600,
                        }}
                      >
                        ACTIVE
                      </span>
                    )}
                  </div>
                  <div
                    style={{
                      fontSize: 11,
                      color: "#666",
                      marginBottom: 6,
                    }}
                  >
                    {z.zips.length} zip{z.zips.length === 1 ? "" : "s"} &middot;{" "}
                    {zoneJobTotal(z).toLocaleString()} jobs
                  </div>
                  {z.zips.length > 0 && (
                    <div
                      style={{
                        display: "flex",
                        flexWrap: "wrap",
                        gap: 3,
                        marginBottom: 6,
                        maxHeight: 70,
                        overflowY: "auto",
                      }}
                    >
                      {[...z.zips].sort().map((zip) => (
                        <span
                          key={zip}
                          onClick={(e) => {
                            e.stopPropagation();
                            if (!z.locked) removeFromZone(z.id, zip);
                          }}
                          style={{
                            background: "#fff",
                            border: `1px solid ${z.color}`,
                            color: z.color,
                            padding: "1px 5px",
                            borderRadius: 3,
                            fontSize: 10,
                            fontFamily: "monospace",
                            cursor: z.locked ? "default" : "pointer",
                          }}
                          title={
                            z.locked
                              ? "Zone is locked"
                              : "Click to remove from zone"
                          }
                        >
                          {zip}
                        </span>
                      ))}
                    </div>
                  )}
                  {z.zips.length > 0 &&
                    (() => {
                      const breakdown = zoneBreakdown(z);
                      if (breakdown.length === 0) return null;
                      const total = breakdown.reduce(
                        (s, b) => s + b.count,
                        0
                      );
                      return (
                        <div style={{ marginBottom: 6 }}>
                          <div
                            style={{
                              display: "flex",
                              height: 8,
                              borderRadius: 3,
                              overflow: "hidden",
                              marginBottom: 4,
                              background: "#eee",
                            }}
                          >
                            {breakdown.map((b) => (
                              <div
                                key={b.name}
                                title={`${b.name}: ${b.count.toLocaleString()} (${(b.pct * 100).toFixed(1)}%)`}
                                style={{
                                  width: `${b.pct * 100}%`,
                                  background: b.color,
                                }}
                              />
                            ))}
                          </div>
                          <div
                            style={{
                              display: "grid",
                              gridTemplateColumns:
                                "10px 1fr auto auto",
                              columnGap: 6,
                              rowGap: 1,
                              fontSize: 10,
                              color: "#444",
                            }}
                          >
                            {breakdown.map((b) => (
                              <Fragment key={b.name}>
                                <span
                                  style={{
                                    width: 8,
                                    height: 8,
                                    borderRadius: 2,
                                    background: b.color,
                                    alignSelf: "center",
                                  }}
                                />
                                <span style={{ whiteSpace: "nowrap" }}>
                                  {b.name}
                                </span>
                                <span
                                  style={{
                                    fontVariantNumeric: "tabular-nums",
                                    textAlign: "right",
                                  }}
                                >
                                  {b.count.toLocaleString()}
                                </span>
                                <span
                                  style={{
                                    fontVariantNumeric: "tabular-nums",
                                    color: "#888",
                                    textAlign: "right",
                                  }}
                                >
                                  {((b.count / total) * 100).toFixed(0)}%
                                </span>
                              </Fragment>
                            ))}
                          </div>
                        </div>
                      );
                    })()}
                  <div
                    style={{ display: "flex", gap: 4 }}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <button
                      onClick={() => toggleLock(z.id)}
                      style={{
                        flex: 1,
                        padding: "3px 6px",
                        fontSize: 11,
                        background: z.locked ? z.color : "#fff",
                        color: z.locked ? "#fff" : "#1a1a1a",
                        border: `1px solid ${z.locked ? z.color : "#d3d1c7"}`,
                        borderRadius: 4,
                        cursor: "pointer",
                      }}
                    >
                      {z.locked ? "Unlock" : "Lock"}
                    </button>
                    <button
                      onClick={() => copyZips(z)}
                      disabled={z.zips.length === 0}
                      style={{
                        flex: 1,
                        padding: "3px 6px",
                        fontSize: 11,
                        background: "#fff",
                        border: "1px solid #d3d1c7",
                        borderRadius: 4,
                        cursor:
                          z.zips.length === 0 ? "not-allowed" : "pointer",
                      }}
                    >
                      Copy zips
                    </button>
                    <button
                      onClick={() => deleteZone(z.id)}
                      disabled={z.locked}
                      style={{
                        padding: "3px 8px",
                        fontSize: 11,
                        background: "#fff",
                        border: "1px solid #d3d1c7",
                        borderRadius: 4,
                        cursor: z.locked ? "not-allowed" : "pointer",
                        color: z.locked ? "#aaa" : "#a02525",
                      }}
                    >
                      Delete
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Coverage summary */}
          <div
            style={{
              borderTop: "1px solid #eee",
              marginTop: 12,
              paddingTop: 8,
              fontSize: 11,
              color: "#666",
            }}
          >
            Coverage: {assignedZips.size} / {visibleZips.length} visible zips
            assigned
          </div>
        </div>
      </div>

      {/* (Original CT/NY legend removed — heatmap legend above replaces it) */}
      <div style={{ display: "none" }}>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 12,
            marginBottom: 8,
          }}
        >
          {CT_LEGEND.map(([label, color]) => (
            <span
              key={label}
              style={{ display: "flex", alignItems: "center", gap: 4 }}
            >
              <span
                style={{
                  width: 12,
                  height: 12,
                  borderRadius: 2,
                  background: color,
                }}
              />
              {label}
            </span>
          ))}
        </div>
        <div style={{ fontWeight: 500, marginBottom: 4, color: "#1a1a1a" }}>
          New York (Westchester)
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}>
          {NY_LEGEND.map(([label, color]) => (
            <span
              key={label}
              style={{ display: "flex", alignItems: "center", gap: 4 }}
            >
              <span
                style={{
                  width: 12,
                  height: 12,
                  borderRadius: 2,
                  background: color,
                }}
              />
              {label}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}
